CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at_ms INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('local','zentao')), status TEXT NOT NULL CHECK(status IN ('todo','doing','done','closed')), revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE categories(id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE providers(id TEXT PRIMARY KEY, name TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE models(id TEXT PRIMARY KEY, name TEXT NOT NULL, provider_id TEXT NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE skills(id TEXT PRIMARY KEY, name TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE agents(id TEXT PRIMARY KEY, name TEXT NOT NULL, model_id TEXT REFERENCES models(id) ON DELETE RESTRICT, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE agent_skills(agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE RESTRICT, PRIMARY KEY(agent_id,skill_id));
CREATE TABLE knowledge_bases(id TEXT PRIMARY KEY, name TEXT NOT NULL, embedding_model_id TEXT NOT NULL REFERENCES models(id) ON DELETE RESTRICT, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE tasks(id TEXT PRIMARY KEY, title TEXT NOT NULL, project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, source TEXT NOT NULL CHECK(source IN ('local','zentao')), status TEXT NOT NULL CHECK(status IN ('todo','doing','done','closed')), priority TEXT NOT NULL CHECK(priority IN ('low','normal','high')), start_at_ms INTEGER, end_at_ms INTEGER, schedule_date TEXT, due_date TEXT, timezone TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), CHECK(end_at_ms IS NULL OR (start_at_ms IS NOT NULL AND end_at_ms > start_at_ms)));
CREATE INDEX tasks_project_status ON tasks(project_id,status);
CREATE INDEX tasks_schedule ON tasks(schedule_date,start_at_ms,end_at_ms);
CREATE TABLE apps(id TEXT PRIMARY KEY, name TEXT NOT NULL, category_id TEXT REFERENCES categories(id) ON DELETE RESTRICT, url TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE conversations(id TEXT PRIMARY KEY, title TEXT NOT NULL, agent_id TEXT REFERENCES agents(id) ON DELETE RESTRICT, knowledge_base_id TEXT REFERENCES knowledge_bases(id) ON DELETE RESTRICT, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE RESTRICT, role TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL, sequence INTEGER NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(conversation_id,sequence));
CREATE TABLE documents(id TEXT PRIMARY KEY, knowledge_base_id TEXT NOT NULL REFERENCES knowledge_bases(id) ON DELETE RESTRICT, name TEXT NOT NULL, status TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE entity_history(entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL, created_at_ms INTEGER NOT NULL, PRIMARY KEY(entity_type,entity_id,revision));
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)));
CREATE TABLE connections(id TEXT PRIMARY KEY, name TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
